function questionBank(){
 return [...SHORT.map(q=>({...q,sourceType:'Curated practice',answerVerified:true,difficulty:'Medium'})),...D.questions.map(q=>({...q,type:q.type==='MCQ'?'MCQ':q.type,answerVerified:q.answerVerified!==false,sourceType:q.sourceType||(q.verifiedSource?'Source-checked PYQ':'Curated practice'),difficulty:q.difficulty||'Medium'}))];
}
function questionMarks(q){return q.marks||((q.type==='MCQ')?1:(q.type==='Short'?2:(q.type==='Long'?7:0)));}
function isCurrentSemesterPyq(q){
 const wanted=subj(q.s)?.code;
 const codes=String(q.courseCode||'').split(/[\\/;, ]+/).filter(Boolean);
 return !!(q.verifiedSource&&Number(q.semester)===4&&wanted&&codes.includes(wanted));
}
function isSupplementary(q){
 const type=String(q.sourceType||'').toLowerCase();
 return type.includes('supplementary')||!!(q.verifiedSource&&q.semester!==undefined&&!isCurrentSemesterPyq(q));
}
function isCurated(q){return !q.verifiedSource&&!isSupplementary(q);}
function questionWasAnswered(q){
 if(typeof state.questionAnswers[q.id]==='number')return true;
 return state.scores.some(a=>Array.isArray(a.items)&&a.items.some(x=>x.id===q.id)&&typeof (a.answers||{})[q.id]==='number');
}
function questionWasIncorrect(q){
 if(typeof state.questionAnswers[q.id]==='number'&&state.questionAnswers[q.id]!==q.a)return true;
 return state.scores.some(a=>Array.isArray(a.items)&&a.items.some(x=>x.id===q.id)&&typeof (a.answers||{})[q.id]==='number'&&(a.answers||{})[q.id]!==x.a);
}
