'short-dbms-1':'DBMS-0-3','short-dbms-2':'DBMS-1-2','short-etc-1':'ETC-0-0','short-etc-2':'ETC-4-0','coa-pyq-2022-q1a':'COA-1-0','coa-pyq-2022-q1b':'COA-3-0'
