function questionMeta(q){
 const t=topicById(QUESTION_TOPIC_MAP[q.id]||q.topicId),s=subj(q.s);
 return {topic:t||null,subject:s||null,unitIndex:t?t.unitIndex:null,unitKey:t?t.s+':'+t.unitIndex:'UNMAPPED',priority:q.priority||t?.priority||'Unrated',year:q.year||q.sourceYear||null,source:q.sourceType||(q.verifiedSource?'Source-checked PYQ':'Curated practice'),marks:questionMarks(q),difficulty:q.difficulty||t?.priority||'Medium',currentSemesterMatch:isCurrentSemesterPyq(q),supplementary:isSupplementary(q),verifiedAnswer:q.answerVerified!==false,sourcePage:q.sourcePage||null,paperPage:q.paperPage||null,courseCode:q.courseCode||null,semester:q.semester||null,paper:q.paper||null,sourceName:q.sourceName||null};
}
