 '<div class="section-heading"><div><h2>Recent MCQ attempts</h2><p>Completed sets can be reopened for answer review.</p></div></div><section class="panel">'+(state.scores.filter(r=>r.attemptType==='mcq-practice'||Array.isArray(r.items)&&r.items.length&&r.items.every(x=>x.type==='MCQ')).length?state.scores.filter(r=>r.attemptType==='mcq-practice'||Array.isArray(r.items)&&r.items.length&&r.items.every(x=>x.type==='MCQ')).slice(-8).reverse().map(r=>'<div class="exam-row"><div class="exam-date-block"><strong>'+r.percent+'%</strong><small>SCORE</small></div><div class="exam-info"><div class="exam-title">'+esc(r.subject==='ALL'?'All subjects':subj(r.subject)?.short||r.subject)+' · '+(r.correct||0)+'/'+r.total+' correct</div><div class="exam-code">'+dateLabel(r.date)+' · '+(r.accuracy??r.percent)+'% accuracy · '+(r.unanswered||0)+' skipped</div></div><button class="btn btn-sm" data-go="#/results/'+r.id+'">Review →</button></div>').join(''):'<p class="muted text-sm">No completed MCQ attempts yet. The first completed set will be saved here.</p>')+'</section>'+
 '<div class="section-heading"><div><h2>Other practice modes</h2><p>Written answers stay separate from automatically scored MCQs.</p></div></div><div class="grid grid-3"><section class="panel"><span class="badge badge-purple">Short answers</span><h2 style="margin-top:12px">Definitions drill</h2><p class="muted text-sm">Practise concise definitions and distinctions.</p><button class="btn" data-go="#/pyqs?type=Short">Open short-answer bank →</button></section><section class="panel"><span class="badge badge-blue">Written practice</span><h2 style="margin-top:12px">Long-answer rehearsal</h2><p class="muted text-sm">Reveal suggested structures and compare your own written answer.</p><button class="btn" data-action="show-long">Browse long answers →</button></section><section class="panel"><span class="badge badge-green">Weak topics</span><h2 style="margin-top:12px">Targeted review</h2><p class="muted text-sm">Revisit incorrect answers and flashcards due today.</p><button class="btn" data-go="#/revision">Open revision hub →</button></section></div>';
